        def apply_argument_empty_line_policy(node)
          @argument_layout_node = node
          return if node.single_line? || node.arguments.empty? || argument_receiver_on_other_line?(node)
          each_argument_extra_line(node) do |range|
            investigation_host.add_offense(range) do |corrector|
              corrector.remove(range)
            end
          end
        end

        def each_argument_extra_line(node)
          @argument_layout_node = node
          argument_blank_lines(node).each do |line|
            buffer = host_buffer
            prepare_layout_range_context(buffer, line)
            yield layout_line_start_range(buffer, line)
          end
        end

        def argument_blank_lines(node)
          @argument_layout_node = node
          lines = argument_processed_lines(node)
          lines.select! { |code, _| code.empty? }
          lines.map { |_, line| line }
        end

        def argument_processed_lines(node)
          @argument_layout_node = node
          argument_candidate_line_numbers(node).each_with_object([]) do |num, array|
            array << [host_source_line(num - 1), num]
          end
        end

        def argument_candidate_line_numbers(node)
          @argument_layout_node = node
          inner_lines = []
          line_nums = node.arguments.each_with_object([]) do |arg_node, lines|
            lines << argument_outer_lines(arg_node)
            inner_lines << argument_inner_lines(arg_node) if arg_node.multiline?
          end
          line_nums.flatten.uniq - inner_lines.flatten - argument_outer_lines(node)
        end

